import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"プラグイン管理","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/plugins.md","filePath":"ja-JP/user-guide/settings/plugins.md","lastUpdated":1788617342000}'),n={name:"ja-JP/user-guide/settings/plugins.md"};function s(l,o,i,d,g,c){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="プラグイン管理" tabindex="-1">プラグイン管理 <a class="header-anchor" href="#プラグイン管理" aria-label="Permalink to &quot;プラグイン管理&quot;">​</a></h1><p>Lertaro は、高度にモジュール化されたプラグインアーキテクチャを備えています。コア拡張機能、ネイティブ C# プラグイン、Flow Launcher コミュニティプラグインを <strong>設定 → プラグイン</strong> で一元管理できます。</p><h2 id="_1-画面構成と-sdk-バージョン" tabindex="-1">1. 画面構成と SDK バージョン <a class="header-anchor" href="#_1-画面構成と-sdk-バージョン" aria-label="Permalink to &quot;1. 画面構成と SDK バージョン&quot;">​</a></h2><ul><li><strong>Plugin SDK バッジ</strong>：画面右上に現在読み込まれている <code>Lertaro.PluginSdk</code> のバージョンが表示されます。クリックすると <a href="./../../dev-guide/"><strong>開発者ガイド</strong></a> に直接移動できます。</li><li><strong>左右 2 ペインの独立スクロール</strong>：左側にインストール済みプラグイン一覧、右側に選択したプラグインの詳細と設定フォームが配置され、互いに干渉せず独立してスクロールできます。</li></ul><h2 id="_2-プラグイン詳細とコンポーネント設定" tabindex="-1">2. プラグイン詳細とコンポーネント設定 <a class="header-anchor" href="#_2-プラグイン詳細とコンポーネント設定" aria-label="Permalink to &quot;2. プラグイン詳細とコンポーネント設定&quot;">​</a></h2><p>左側でプラグインを選択すると、右側にアイコン、名前、バージョン、概要が表示されます。</p><h3 id="詳細タブ-details" tabindex="-1">詳細タブ（Details） <a class="header-anchor" href="#詳細タブ-details" aria-label="Permalink to &quot;詳細タブ（Details）&quot;">​</a></h3><ul><li><strong>コンポーネント一覧</strong>：登録されているすべての機能コンポーネント（検索ソース、アクションプロバイダー、クイックナビゲーション項目、プレビューハンドラー等）を一覧表示。</li><li><strong>コンポーネント単位の個別スイッチ</strong>：各コンポーネントに <strong>有効/無効チェックボックス</strong> が用意されています。ロックアイコンが付いた必須コンポーネントは無効化できません。</li><li><strong>一括選択 / 解除</strong>：グループ内に複数の項目がある場合、「すべて選択/解除」リンクから一括切り替えが可能。</li><li><strong>詳細ツールチップ</strong>：各項目の <strong>(!)</strong> にマウスを合わせると、コンポーネントの動作説明が表示されます。</li></ul><h3 id="設定タブ-configure" tabindex="-1">設定タブ（Configure） <a class="header-anchor" href="#設定タブ-configure" aria-label="Permalink to &quot;設定タブ（Configure）&quot;">​</a></h3><ul><li><strong>インライン設定フォーム</strong>：プラグイン独自の設定項目が画面内に直接描画されます（テキスト入力、数値スライダー、トグル、ドロップダウン、グループタブ等）。</li><li><strong>アイコン入力フィールド</strong>：スキーマキーが <code>Icon</code> のテキスト入力にはアイコンのプレビューが表示され、WPF Path Data を入力できます。完全な SVG/XML を貼り付けるとパスデータを自動的に抽出して結合し、無効な内容は消去してテーマ対応のダイアログで通知します。</li><li><strong>複数行設定エディター</strong>：<code>StringList</code> フィールドを展開したエディターでは自動折り返しを使用できます。実際の改行には判別用の薄い <code>↵</code> マーカーが表示されますが、これは表示専用で、保存値やコピーしたテキストには含まれません。</li><li><strong>安全な変更適用と破棄</strong>：<strong>OK</strong> をクリックするまで変更はメモリ上にのみ保持され、保存せずに別のプラグインへ切り替えると変更内容は破棄されて元の状態に戻ります。</li></ul><h3 id="coreextensions-の検索種類フィルター" tabindex="-1">CoreExtensions の検索種類フィルター <a class="header-anchor" href="#coreextensions-の検索種類フィルター" aria-label="Permalink to &quot;CoreExtensions の検索種類フィルター&quot;">​</a></h3><p><strong>設定 → プラグイン → CoreExtensions → 設定 → 検索フィルター</strong>では、全体検索ウィンドウの左側に表示する種類フィルターを管理できます。ファイルとフォルダーは常に使用でき、ドキュメント、画像、動画のフィルターは個別に無効化できます。</p><p><strong>サイドバーのカスタムフィルター</strong>では、表示名、任意の WPF Path Data アイコン、ワイルドカードルールを指定して追加できます。名前が空の項目や展開後のルールが空になる項目は非表示になり、アイコンを空にすると既定のアイコンが使用されます。名前は表示専用で、<code>@</code> 参照には使われません。<code>@</code> 参照はルール欄でのみ有効で、<code>@キーワード</code> は既存の<strong>カスタムフィルター</strong>一覧にあるキーワードを展開します。そのフィルターが無効でも参照できます。参照は再帰的に展開され、重複するパターンは削除されます。不明または循環した参照からは一致するルールが生成されません。</p><h2 id="_3-flow-launcher-コミュニティプラグインの完全対応" tabindex="-1">3. Flow Launcher コミュニティプラグインの完全対応 <a class="header-anchor" href="#_3-flow-launcher-コミュニティプラグインの完全対応" aria-label="Permalink to &quot;3. Flow Launcher コミュニティプラグインの完全対応&quot;">​</a></h2><p>ネイティブの <code>Lertaro.PluginSdk</code> に加え、<strong>Flow Launcher Bridge</strong> により Flow Launcher の豊富なコミュニティプラグインをそのまま利用できます。</p><h3 id="多言語ランタイムと完全隔離環境" tabindex="-1">多言語ランタイムと完全隔離環境 <a class="header-anchor" href="#多言語ランタイムと完全隔離環境" aria-label="Permalink to &quot;多言語ランタイムと完全隔離環境&quot;">​</a></h3><ul><li><strong>幅広い言語のサポート</strong>：<strong>C# (.NET)</strong>、<strong>Python 3.12</strong>、<strong>Node.js v20 LTS</strong>、および実行ファイル（<code>.exe</code>）形式の Flow プラグインをネイティブレベルで実行。</li><li><strong>システム環境を汚さない独立環境</strong>：Python（<code>FlowData\\PythonEmbeded-{arch}</code>）や Node.js（<code>FlowData\\NodeEmbeded-{arch}</code>）ランタイムは Lertaro のデータディレクトリ内に自動配置され、Windows のシステム PATH を変更しません。</li><li><strong>依存関係の自動インストール</strong>：初回読み込み時、<code>requirements.txt</code>（Python pip）や <code>package.json</code>（Node.js npm）に基づいて必要なライブラリをバックグラウンドで自動取得・構築します。</li></ul><h3 id="ストア機能とコマンドライン管理" tabindex="-1">ストア機能とコマンドライン管理 <a class="header-anchor" href="#ストア機能とコマンドライン管理" aria-label="Permalink to &quot;ストア機能とコマンドライン管理&quot;">​</a></h3><p>検索ボックスから直接 Flow プラグインを管理できます：</p><ul><li><strong><code>flow install &lt;キーワード&gt;</code></strong>：Flow.Launcher 公式リポジトリを検索し、ワンクリックでダウンロード・展開・依存関係のセットアップを実行。</li><li><strong><code>flow update</code></strong>：インストール済み Flow プラグインの更新を確認し、一括アップデート。</li><li><strong><code>flow uninstall &lt;プラグイン名&gt;</code></strong>：プラグインをアンインストールし、ディレクトリをクリーンアップ。</li><li><strong>手動追加</strong>：ダウンロードしたフォルダーを <code>&lt;ユーザーデータ&gt;\\FlowData\\Plugins\\</code> に配置しても利用可能。</li></ul><h3 id="設定、トリガー文字、リッチプレビュー" tabindex="-1">設定、トリガー文字、リッチプレビュー <a class="header-anchor" href="#設定、トリガー文字、リッチプレビュー" aria-label="Permalink to &quot;設定、トリガー文字、リッチプレビュー&quot;">​</a></h3><ul><li><strong>ActionKeyword の変更</strong>：<strong>設定 → プラグイン → Flow Launcher Bridge → 設定</strong> で、各 Flow プラグインの有効/無効化や起動キーワード（ActionKeyword）を個別に変更可能（設定は <code>FlowData\\Settings\\Plugins.json</code> に安全に保持）。</li><li><strong>動的設定フォーム</strong>：YAML/JSON テンプレート（<code>SettingsTemplate.yaml</code>/<code>.json</code>）や C# WPF 設定パネル（<code>ISettingProvider</code>）に完全対応し、ダーク/ライトテーマや多言語表示にも適合。</li><li><strong>WebView2 によるリッチプレビュー</strong>：辞書（MDict）、天気予報、API デバッグ、Web ページスナップショットなどのリッチなプレビューを QuickLook パネル内に美しく自動描画。</li><li><strong>ホスト機能との高度な統合</strong>：Flow プラグインが API 経由でフォルダーを開く際はホスト設定のサードパーティ製ファイルマネージャーに自動連携し、メッセージボックスはホストのテーマダイアログで描画され、プラグインログは設定画面のログビューアーに統合されます。</li><li><strong>一覧表示</strong>：検索ボックスに <code>flow</code> と入力するだけで、読み込まれているすべての Flow プラグインとそのキーワードを確認できます。プラグインを選択すると、設定画面の対応する設定グループが開きます。</li></ul><h2 id="_4-オーディオデバイスセレクター" tabindex="-1">4. オーディオデバイスセレクター <a class="header-anchor" href="#_4-オーディオデバイスセレクター" aria-label="Permalink to &quot;4. オーディオデバイスセレクター&quot;">​</a></h2><p><strong>オーディオデバイスセレクター</strong>は Windows 専用のネイティブプラグインです。<code>ad</code> と入力すると現在アクティブな出力デバイスと入力デバイスが一覧表示され、デバイスを選択すると対応する既定のマルチメディアデバイスに設定されます。トリガーキーワードの後にデバイス名を追加して結果を絞り込むこともできます。</p><p>設定ではトリガーキーワードを変更し、結果にフレンドリ名、デバイス名、デバイスの説明のどれを表示するかを選択できます。既定の出力または入力エンドポイントを変更できますが、音量、ミュート、アプリごとのオーディオルーティングは制御しません。</p><h2 id="_5-コンテンツ検索" tabindex="-1">5. コンテンツ検索 <a class="header-anchor" href="#_5-コンテンツ検索" aria-label="Permalink to &quot;5. コンテンツ検索&quot;">​</a></h2><p><strong>コンテンツ検索</strong>プラグインは、設定したローカル文書の本文を検索します。<strong>設定</strong>タブでは、トリガーキーワード、監視フォルダー、対象拡張子、ファイルごとのサイズ上限、インデックスサイズ上限、完全パスの除外正規表現を設定できます。既定のトリガーは <code>cs</code> なので、<code>cs プロジェクト計画</code> と入力すると本文を検索し、スニペット付きで一致ファイルを表示します。</p><p>設定には<strong>インデックスをクリア</strong>と<strong>インデックスを再構築</strong>もあります。クリアはコンテンツインデックスだけを削除し、再構築は削除後にすべての監視フォルダーを再スキャンします。どちらも Lertaro の通常のファイル名インデックスは削除しません。</p><h2 id="_6-プラグイン実行状態" tabindex="-1">6. プラグイン実行状態 <a class="header-anchor" href="#_6-プラグイン実行状態" aria-label="Permalink to &quot;6. プラグイン実行状態&quot;">​</a></h2><p><strong>設定 → プラグイン → 実行状態</strong>タブでは、Lertaro の実行中にインストール済みプラグインで発生したホスト側の呼び出しを確認できます。値はプラグイン単位で集計され、タブを開いている間更新されます。</p><ul><li><strong>プラグインの絞り込み</strong>：絞り込みボックスでプラグイン名をあいまい検索できます。</li><li><strong>並べ替え可能な列</strong>：列見出しをクリックすると、昇順、降順、既定のプラグイン順の順に切り替わります。</li><li><strong>表示される指標</strong>：呼び出し回数、平均所要時間、直近の所要時間、最大所要時間、マネージド割り当て、検出された例外。</li><li><strong>セッション範囲</strong>：統計は現在の Lertaro プロセス中に累積し、再起動するとリセットされます。ゼロは該当する計測呼び出しがまだ記録されていないことを示します。マネージド割り当ては計測呼び出しによるメモリ割り当てであり、プラグインのプライベートメモリ使用量全体ではありません。</li></ul>',31)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
